#!/usr/bin/env python3

"""
Script to reproduce the issue with annotated types in serialization_strategy.
"""

from dataclasses import dataclass
from typing import Annotated
from mashumaro import DataClassDictMixin


# Define annotated types
PositiveInt = Annotated[int, "PositiveInt"]
NegativeInt = Annotated[int, "NegativeInt"]


def deserialize_positive_int(value):
    print(f"Deserializing positive int: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    print(f"Deserializing negative int: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
            }
        }


def test_deserialization():
    """Test that annotated types are properly handled in deserialization."""
    print("Testing deserialization...")

    # This should work - using the custom deserializers
    try:
        obj = MyClass.from_dict({"positive_int": 5, "negative_int": -3})
        print(f"Success: {obj}")
        assert obj.positive_int == 5
        assert obj.negative_int == -3
        print("✓ Deserialization worked correctly")
    except Exception as e:
        print(f"✗ Deserialization failed: {e}")
        return False

    # This should fail - positive int deserializer should reject negative value
    try:
        obj = MyClass.from_dict({"positive_int": -5, "negative_int": -3})
        print(f"✗ Should have failed but got: {obj}")
        return False
    except ValueError as e:
        if "value < 0" in str(e):
            print("✓ Correctly rejected negative value for PositiveInt")
        else:
            print(f"✗ Wrong error: {e}")
            return False
    except Exception as e:
        print(f"✗ Unexpected error: {e}")
        return False

    return True


def test_serialization():
    """Test that annotated types are properly handled in serialization."""
    print("\nTesting serialization...")

    # This should work 
    try:
        obj = MyClass(positive_int=5, negative_int=-3)
        data = obj.to_dict()
        print(f"Serialized: {data}")
        assert data == {"positive_int": 5, "negative_int": -3}
        print("✓ Serialization worked correctly")
        return True
    except Exception as e:
        print(f"✗ Serialization failed: {e}")
        return False


if __name__ == "__main__":
    print("Reproducing annotated types serialization strategy issue...")

    success = test_deserialization()
    success &= test_serialization()

    if success:
        print("\n✓ All tests passed!")
    else:
        print("\n✗ Some tests failed!")
        exit(1)

