"""
Test to demonstrate the current issue: annotated types are not distinguished 
from their base types in serialization_strategy lookup.
"""

from dataclasses import dataclass
from typing import Annotated
from mashumaro import DataClassDictMixin


# Define annotated types
PositiveInt = Annotated[int, "PositiveInt"]
NegativeInt = Annotated[int, "NegativeInt"]


def deserialize_annotated_int(value):
    """Deserializer that should only apply to annotated ints."""
    print(f"Annotated int deserializer called with: {value}")
    return value * 100  # Multiply by 100 to make it obvious


@dataclass
class TestClass(DataClassDictMixin):
    regular_int: int
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        # This should ONLY apply to annotated int types, not regular int
        serialization_strategy = {
            Annotated[int, "PositiveInt"]: {
                "deserialize": deserialize_annotated_int,
            },
            Annotated[int, "NegativeInt"]: {
                "deserialize": deserialize_annotated_int,
            }
        }


def test_distinction():
    """Test that annotated types are distinguished from regular types."""
    print("Testing distinction between annotated and regular types...")

    try:
        # This should use the custom deserializer for annotated fields
        # but NOT for the regular int field
        obj = TestClass.from_dict({
            "regular_int": 5,
            "positive_int": 3, 
            "negative_int": 7
        })

        print(f"Result: {obj}")

        # regular_int should be 5 (no multiplier)
        # positive_int should be 300 (3 * 100)  
        # negative_int should be 700 (7 * 100)

        if obj.regular_int == 5 and obj.positive_int == 300 and obj.negative_int == 700:
            print("✓ SUCCESS: Annotated types are properly distinguished!")
            return True
        else:
            print("✗ FAILURE: Types are not being distinguished properly")
            print(f"  regular_int: {obj.regular_int} (expected 5)")
            print(f"  positive_int: {obj.positive_int} (expected 300)")  
            print(f"  negative_int: {obj.negative_int} (expected 700)")
            return False

    except Exception as e:
        print(f"✗ ERROR: {e}")
        import traceback
        traceback.print_exc()
        return False


if __name__ == "__main__":
    success = test_distinction()
    if not success:
        print("\nThe issue is reproduced - annotated types are not distinguished from regular types")
        exit(1)
    else:
        print("\nIssue is fixed!")

