    """Test deserialization."""
    print("=== Testing DESERIALIZATION ===")

    try:
        obj = TestClass.from_dict({
            "regular_int": 5,
            "positive_int": 3, 
            "negative_int": 7
        })

        print(f"Deserialized object: {obj}")

        # Check values
        if obj.regular_int == 5 and obj.positive_int == 300 and obj.negative_int == 700:
            print("✓ Deserialization works correctly")
            return obj
        else:
            print("✗ Deserialization failed") 
            return None

    except Exception as e:
        print(f"✗ Deserialization error: {e}")
        import traceback
        traceback.print_exc()
        return None


def test_serialize(obj):
    """Test serialization."""
    print("\n=== Testing SERIALIZATION ===")

    try:
        data = obj.to_dict()
        print(f"Serialized data: {data}")

        # Check values
        # regular_int should stay 5
        # positive_int should become 3 (300 // 100) 
        # negative_int should become 7 (700 // 100)

        if data["regular_int"] == 5 and data["positive_int"] == 3 and data["negative_int"] == 7:
            print("✓ Serialization works correctly")
            return True
        else:
            print("✗ Serialization failed")
