            print(f"  negative_int: {data['negative_int']} (expected 7)")
            return False

    except Exception as e:
        print(f"✗ Serialization error: {e}")
        import traceback
        traceback.print_exc()
        return False


if __name__ == "__main__":
    obj = test_deserialize()
    if obj:
        success = test_serialize(obj)
        if success:
            print("\n✓ Both directions work!")
        else:
            print("\n✗ Serialization has issues")
            exit(1)
    else:
        print("\n✗ Deserialization failed")
        exit(1)

